    public void demonstrateCreation() {
        CompletableFuture<String> f1 = CompletableFuture.supplyAsync(() -> fetchProfile("u42"), ioPool);
        CompletableFuture<Void> f2 = CompletableFuture.runAsync(() -> writeAudit("u42"), ioPool);
