public CompletableFuture<String> loadProfileWithTimeout(String userId) {
    return CompletableFuture
        .supplyAsync(() -> callRemoteService(userId), ioPool)
        .orTimeout(500, TimeUnit.MILLISECONDS)
        .completeOnTimeout("DEFAULT_PROFILE", 300, TimeUnit.MILLISECONDS)
        .exceptionally(ex -> {
            Throwable root = (ex instanceof CompletionException) ? ex.getCause() : ex;
            return "Fallback(" + root.getMessage() + ")";
        });
}
